class GpuDefs:
    def __init__(self, name, mode, chipid, constants):
        self.NAME = name
        self.MODE = mode
        self.CHIPID = chipid
        self._constants = constants

    def __getattr__(self, name):
        try:
            return self._constants[name]
        except KeyError:
            raise AttributeError(name) from None

    def __dir__(self):
        return sorted(set(super().__dir__()) | self._constants.keys())

    def VERTEX2F(self, x, y):
        return ((1 << 30) | (((x)&32767) << 15) | (((y)&32767) << 0))

    def VERTEX2II(self, x, y, handle, cell):
        return ((2 << 30) | (((x)&511) << 21) | (((y)&511) << 12) | (((handle)&31) << 7) | (((cell)&127) << 0))

    def BITMAP_SOURCE(self, addr):
        return ((1 << 24) | ((addr & (self.BITMAP_ADDR_MASK >> 1)) if addr < 0 else (addr & self.BITMAP_ADDR_MASK)))

    def BITMAP_SOURCE2(self, flash_or_ram, addr):
        return ((1 << 24) | ((flash_or_ram) << 23) | (((addr) & (self.BITMAP_ADDR_MASK >> 1)) << 0))

    def CLEAR_COLOR_RGB(self, red, green, blue):
        return ((2 << 24) | (((red)&255) << 16) | (((green)&255) << 8) | (((blue)&255) << 0))

    def TAG(self, s):
        return ((3 << 24) | (((s)&self.TAG_DL_MASK) << 0))

    def COLOR_RGB(self, red, green, blue):
        return ((4 << 24) | (((red)&255) << 16) | (((green)&255) << 8) | (((blue)&255) << 0))

    def BITMAP_HANDLE(self, handle):
        return ((5 << 24) | (((handle)&self.BITMAP_HANDLE_MASK) << 0))

    def CELL(self, cell):
        return ((6 << 24) | (((cell)&127) << 0))

    def BITMAP_LAYOUT(self, format, linestride, height):
        return ((7 << 24) | (((format)&31) << 19) | (((linestride)&1023) << 9) | (((height)&511) << 0))

    def BITMAP_SIZE(self, filter, wrapx, wrapy, width, height):
        return ((8 << 24) | (((filter)&1) << 20) | (((wrapx)&1) << 19) | (((wrapy)&1) << 18) | (((width)&511) << 9) | (((height)&511) << 0))

    def ALPHA_FUNC(self, func, ref):
        return ((9 << 24) | (((func)&7) << 8) | (((ref)&255) << 0))

    def STENCIL_FUNC(self, func, ref, mask):
        return ((10 << 24) | (((func)&7) << 16) | (((ref)&255) << 8) | (((mask)&255) << 0))

    def BLEND_FUNC(self, src, dst):
        return ((11 << 24) | (((src)&7) << 3) | (((dst)&7) << 0))

    def STENCIL_OP(self, sfail, spass):
        return ((12 << 24) | (((sfail)&7) << 3) | (((spass)&7) << 0))

    def POINT_SIZE(self, size):
        return ((13 << 24) | (((size)&8191) << 0))

    def LINE_WIDTH(self, width):
        return ((14 << 24) | (((width)&4095) << 0))

    def CLEAR_COLOR_A(self, alpha):
        return ((15 << 24) | (((alpha)&255) << 0))

    def COLOR_A(self, alpha):
        return ((16 << 24) | (((alpha)&255) << 0))

    def CLEAR_STENCIL(self, s):
        return ((17 << 24) | (((s)&255) << 0))

    def CLEAR_TAG(self, s):
        return ((18 << 24) | (((s)&self.TAG_DL_MASK) << 0))

    def STENCIL_MASK(self, mask):
        return ((19 << 24) | (((mask)&255) << 0))

    def TAG_MASK(self, mask):
        return ((20 << 24) | (((mask)&1) << 0))

    def BITMAP_TRANSFORM_C(self, c):
        return ((23 << 24) | (((c)&16777215) << 0))

    def BITMAP_TRANSFORM_F(self, f):
        return ((26 << 24) | (((f)&16777215) << 0))

    def BITMAP_TRANSFORM_A_EXT(self, p, v):
        return ((21 << 24) | (((p)&1) << 17) | (((v)&131071) << 0))

    def BITMAP_TRANSFORM_B_EXT(self, p, v):
        return ((22 << 24) | (((p)&1) << 17) | (((v)&131071) << 0))

    def BITMAP_TRANSFORM_D_EXT(self, p, v):
        return ((24 << 24) | (((p)&1) << 17) | (((v)&131071) << 0))

    def BITMAP_TRANSFORM_E_EXT(self, p, v):
        return ((25 << 24) | (((p)&1) << 17) | (((v)&131071) << 0))

    def BITMAP_TRANSFORM_A(self, a):
        return self.BITMAP_TRANSFORM_A_EXT(0, a)

    def BITMAP_TRANSFORM_B(self, b):
        return self.BITMAP_TRANSFORM_B_EXT(0, b)

    def BITMAP_TRANSFORM_D(self, d):
        return self.BITMAP_TRANSFORM_D_EXT(0, d)

    def BITMAP_TRANSFORM_E(self, e):
        return self.BITMAP_TRANSFORM_E_EXT(0, e)

    def SCISSOR_XY(self, x, y):
        return ((27 << 24) | (((x)&self.SCISSOR_XY_MASK) << self.SCISSOR_XY_SHIFT) | (((y)&self.SCISSOR_XY_MASK) << 0))

    def SCISSOR_SIZE(self, width, height):
        return ((28 << 24) | (((width)&self.SCISSOR_SIZE_MASK) << self.SCISSOR_SIZE_SHIFT) | (((height)&self.SCISSOR_SIZE_MASK) << 0))

    def CALL(self, dest):
        return ((29 << 24) | (((dest)&65535) << 0))

    def JUMP(self, dest):
        return ((30 << 24) | (((dest)&65535) << 0))

    def BEGIN(self, prim):
        return ((31 << 24) | (((prim)&15) << 0))

    def COLOR_MASK(self, r, g, b, a):
        return ((32 << 24) | (((r)&1) << 3) | (((g)&1) << 2) | (((b)&1) << 1) | (((a)&1) << 0))

    def CLEAR(self, c, s, t):
        return ((38 << 24) | (((c)&1) << 2) | (((s)&1) << 1) | (((t)&1) << 0))

    def VERTEX_FORMAT(self, frac):
        return ((39 << 24) | (((frac)&7) << 0))

    def BITMAP_LAYOUT_H(self, linestride, height):
        return ((40 << 24) | (((linestride)&self.BITMAP_LAYOUT_H_STRIDE_MASK) << 2) | (((height)&3) << 0))

    def BITMAP_SIZE_H(self, width, height):
        return ((41 << 24) | (((width)&3) << 2) | (((height)&3) << 0))

    def PALETTE_SOURCE(self, addr):
        return ((42 << 24) | (((addr)&self.PALETTE_ADDR_MASK) << 0))

    def VERTEX_TRANSLATE_X(self, x):
        return ((43 << 24) | (((x)&131071) << 0))

    def VERTEX_TRANSLATE_Y(self, y):
        return ((44 << 24) | (((y)&131071) << 0))

    def NOP(self):
        return ((45 << 24))

    def BITMAP_EXT_FORMAT(self, format):
        return ((46 << 24) | (((format)&65535) << 0))

    def BITMAP_SWIZZLE(self, r, g, b, a):
        return ((47 << 24) | (((r)&7) << 9) | (((g)&7) << 6) | (((b)&7) << 3) | (((a)&7) << 0))

    def INT_FRR(self):
        return ((48 << 24))

    def INT_PALDAT(self):
        return ((48 << 24))

    def BITMAP_SOURCEH(self, addr):
        return ((49 << 24) | (((addr)&255) << 0))

    def PALETTE_SOURCEH(self, addr):
        return ((50 << 24) | (((addr)&255) << 0))

    def BITMAP_ZORDER(self, o):
        return ((51 << 24) | (((o)&255) << 0))

    def REGION(self, y, h, dest):
        return ((52 << 24) | (((y)&63) << 18) | (((h)&63) << 12) | (((dest)&4095) << 0))

    def SYS_PSEUDO_BASE(self, p):
        return ((53 << 24) | (((p)&2047) << 0))

    def END(self):
        return ((33 << 24))

    def SAVE_CONTEXT(self):
        return ((34 << 24))

    def RESTORE_CONTEXT(self):
        return ((35 << 24))

    def RETURN(self):
        return ((36 << 24))

    def MACRO(self, m):
        return ((37 << 24) | (((m)&1) << 0))

    def DISPLAY(self):
        return ((0 << 24))

    def BITMAP_SOURCE_H(self, addr):
        return self.BITMAP_SOURCEH(addr)

    def PALETTE_SOURCE_H(self, addr):
        return self.PALETTE_SOURCEH(addr)

